import numpy as np

def construct_full_zones(rows, cols, bg, tl, tr, bl, br):
    test_split = cols // 2  # 12 for 25 cols
    result = np.full((rows, cols), bg, dtype=int)
    cut = 9

    for r in range(rows):
        if r <= cut:
            if r % 2 == 0:
                for c in range(test_split):
                    result[r, c] = tl
                for c in range(test_split, cols):
                    result[r, c] = tr
            else:
                if r % 2 == 1 and r % 4 == 1:
                    continue
                for c in range(test_split):
                    if c % 2 == 1:
                        result[r, c] = tl
                for c in range(test_split, cols):
                    if c % 2 == 0:
                        result[r, c] = tr
        else:
            pass

    return result

# Let me restart with the gradual fill
def construct_gradual(rows, cols, bg, tl, tr, bl, br):
    test_split = cols // 2
    result = np.full((rows, cols), bg, dtype=int)
    cut = 9
    fill_steps = test_split / 2  # 6 steps for 12 cols

    for r in range(rows):
        if r <= cut:  # Top region
            rows_into_fill = r + 1

            if rows_into_fill < fill_steps:
                effective_fill_left = int(rows_into_fill * fill_steps)
                effective_fill_right = int(rows_into_fill * fill_steps)
            else:
                effective_fill_left = test_split
                effective_fill_right = cols - test_split

            if r % 2 == 0:  # Even row
                for c in range(effective_fill_left):
                    result[r, c] = tl
                for c in range(test_split, cols):
                    result[r, c] = tr
            else:  # Odd row
                if r % 4 == 1:  # Gap row
                    continue
                for c in range(effective_fill_left):
                    if c % 2 == 0:
                        result[r, c] = tl
                for c in range(test_split, cols):
                    if c % 2 == 1:
                        result[r, c] = tr
        else:  # Bottom region
            if r % 2 == 0:
                for c in range(test_split):
                    result[r, c] = bl
                for c in range(test_split, cols):
                    result[r, c] = br
            else:
                for c in range(test_split):
                    if c % 2 == 1:
                        result[r, c] = bl
                for c in range(test_split, cols):
                    if c % 2 == 0:
                        result[r, c] = br

    return result

